using namespace std;

string markdown_to_html(const string& markdown) {
    // Convert markdown to html
    string html;
    stringstream ss(markdown);
    string line;
    while (getline(ss, line)) {
        // Remove leading and trailing whitespace
        line.erase(remove_if(line.begin(), line.end(), ::isspace), line.end());
        // Convert markdown to html
        vector<string> lines = split(line, '\n');
        for (auto& line : lines) {
            html += "<p>" + line + "</p>";
        }
    }
    return html;
}

vector<string> split(const string& s, char delimiter) {
    vector<string> tokens;
    string token;
    bool in_token = false;
    for (char c : s) {
        if (c == delimiter) {
            if (in_token) {
                tokens.push_back(token);
                in_token = false;
            }
        } else {
            if (!in_token) {
                in_token = true;
            }
            token += c;
        }
    }
    if (in_token) {
        tokens.push_back(token);
    }
    return tokens;
}

int main() {
    string markdown = "This is **bold** text and *italic* text.";
    string html = markdown_to_html(markdown);
    cout << html << endl;
    return 0;
}
